mapper.update:
UPDATE t_product_fee_event
SET capability_kind = #{capabilityKind}, capability_code = #{capabilityCode}, change_version = change_version + 1,
    update_time = #{now}
WHERE product_fee_event_id = #{feeEvent.productFeeEventId} AND change_version = #{feeEvent.changeVersion}

mapper.select:
SELECT  FROM t_product_fee_event

    AND product_code = #{productCode}
    AND term_type = #{termType}

ORDER BY product_fee_event_id
